set -eu
cat >/tmp/journey.js <<'K6_SCRIPT'
import { browser } from 'k6/browser';
import { Rate, Trend } from 'k6/metrics';

const origin = 'http://ecommerce-frontend';
const email = __ENV.K6_TEST_EMAIL;
const password = __ENV.K6_TEST_PASSWORD;
const vus = Number(__ENV.K6_BROWSER_VUS || '1');
const iterations = vus === 1 ? 1 : 3;
if (!Number.isSafeInteger(vus) || vus < 1 || !email || !password) {
  throw new Error('Browser test requires a positive integer VU count and a test account');
}

const passed = new Rate('browser_journey_passed');
const catalog = new Trend('catalog_visible_ms', true);
const loginApi = new Trend('login_api_response_ms', true);
const loginUi = new Trend('login_signed_in_ms', true);
const restored = new Trend('session_and_catalog_visible_ms', true);

export const options = {
  scenarios: {
    browser_journey: {
      executor: 'per-vu-iterations',
      vus, iterations, maxDuration: '100s', gracefulStop: '5s',
      options: { browser: { type: 'chromium' } },
    },
  },
  thresholds: {
    browser_journey_passed: ['rate==1'],
    iterations: ['count>=' + vus * iterations],
  },
};

function requireOk(response, endpoint) {
  if (!response || response.status() !== 200) {
    throw new Error(endpoint + ' expected HTTP 200');
  }
}

export default async function () {
  let page;
  let step = 'launch Chromium';
  let ok = false;
  try {
    page = await browser.newPage();
    const product = page.locator('#app .grid .card:first-child h3');
    const signedIn = page.locator('#auth .hi');
    const wait = { state: 'visible', timeout: 12000 };
    step = 'homepage and catalog';
    let start = Date.now();
    const [catalogResponse, home] = await Promise.all([
      page.waitForResponse(origin + '/api/products', { timeout: 15000 }),
      page.goto(origin + '/', { waitUntil: 'domcontentloaded', timeout: 15000 }),
    ]);
    requireOk(home, 'homepage');
    requireOk(catalogResponse, 'catalog API');
    await product.waitFor(wait);
    catalog.add(Date.now() - start);

    step = 'login form';
    await page.locator('#auth button[onclick*="login"]').click({ timeout: 12000 });
    await page.locator('#a_email').fill(email, { timeout: 12000 });
    await page.locator('#a_pass').fill(password, { timeout: 12000 });
    step = 'login response and signed-in UI';
    start = Date.now();
    const [login] = await Promise.all([
      page.waitForResponse(origin + '/api/auth/login', { timeout: 15000 })
        .then((response) => {
          loginApi.add(Date.now() - start);
          return response;
        }),
      page.locator('#a_go').click({ timeout: 12000 }),
    ]);
    requireOk(login, 'login API');
    await signedIn.waitFor(wait);
    loginUi.add(Date.now() - start);

    step = 'reload and verify authenticated profile and catalog';
    start = Date.now();
    const [profile, products] = await Promise.all([
      page.waitForResponse(origin + '/api/auth/me', { timeout: 15000 }),
      page.waitForResponse(origin + '/api/products', { timeout: 15000 }),
      page.reload({ waitUntil: 'domcontentloaded', timeout: 15000 }),
    ]);
    requireOk(profile, 'profile API');
    requireOk(products, 'catalog API');
    await signedIn.waitFor(wait);
    await product.waitFor(wait);
    restored.add(Date.now() - start);
    ok = true;
  } catch (error) {
    console.error('Browser journey failed at ' + step + ': ' + error.name);
  } finally {
    passed.add(ok);
    if (page) await page.close();
  }
  await new Promise((resolve) => setTimeout(resolve, 1250));
}

export function handleSummary(data) {
  const names = ['browser_journey_passed','iterations','catalog_visible_ms','login_api_response_ms',
    'login_signed_in_ms','session_and_catalog_visible_ms','browser_web_vital_lcp','browser_web_vital_fcp'];
  const metrics = Object.fromEntries(names.filter((name) => data.metrics[name])
    .map((name) => [name, data.metrics[name].values]));
  return { stdout: 'BROWSER_RESULT ' + JSON.stringify({vus, planned: vus * iterations, metrics}) + '\n' };
}
K6_SCRIPT
read_cpu() { awk '$1=="usage_usec"{print $2}' /sys/fs/cgroup/cpu.stat; }
read_throttle() { awk '$1=="nr_throttled"{print $2}' /sys/fs/cgroup/cpu.stat; }
initial=$(read_throttle)
(
  last=$(read_cpu)
  while sleep 1; do
    current=$(read_cpu)
    printf '%s\n' "$((current-last))"
    last=$current
  done
) >/tmp/browser-cpu.log &
monitor=$!
status=0
k6 run --quiet /tmp/journey.js || status=$?
kill "$monitor" 2>/dev/null || true
wait "$monitor" 2>/dev/null || true
awk 'BEGIN{m=0} $1>m{m=$1} END{printf "RUNNER_CPU peak_mcpu=%.0f samples=%d\n",m/1000,NR}' /tmp/browser-cpu.log
printf 'RUNNER_MEMORY peak_bytes=%s throttled_periods=%s\n' "$(cat /sys/fs/cgroup/memory.peak)" "$(($(read_throttle)-initial))"
exit "$status"
